// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner_eoa;

    // whale is address(this); accept ETH so donateToWhale's transfer succeeds
    receive() external payable {}

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
        owner_eoa = __invmut_eoa;
        vm.prank(owner_eoa);
        c.OpenToThePublic();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount <= 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.donate{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
